import {escapeHTML as h,completedCount} from './model.js?v=0.31.0';
import {occupationById,workActivityOptions,settingOptions} from './occupation-data.js?v=0.31.0';

export const navigationGroups=[
 {title:'Discover',items:[['overview','My overview','grid'],['catalog','Majors & careers','search'],['directions','Study directions','shapes']]},
 {title:'About me',items:[['journey','My exploration route','compass'],['results','Bring assessment results','folder'],['explore','Optional reflections','pen'],['reflection','My reflection notes','book']]},
 {title:'Compare',items:[['compare-careers','Compare careers','people'],['money','College & training plans','chart']]},
 {title:'My plan',items:[['report','My exploration brief','book'],['plan','Experiments & next steps','seed'],['lifestyle','Life in Austin','home']]},
 {title:'Sources and privacy',items:[['approach','Research & sources','folder']]}
];
export const navigationItems=navigationGroups.flatMap(g=>g.items);
const options=list=>Array.isArray(list)?list.map(x=>Array.isArray(x)?{id:x[0],label:x[1]}:typeof x==='string'?{id:x,label:x}:{id:x.id??x.value,label:x.label??x.title??x.name}):Object.entries(list||{}).map(([id,label])=>({id,label}));
function resume(state){
 const last=state.exploration?.lastRoute;
 if(last&&/^(journey|results|catalog|compare-careers|plan|report|career\/[a-z0-9-]+|career-reflection\/[a-z0-9-]+)$/.test(last))return {route:last,label:'Resume where you left off'};
 const selected=state.exploration?.savedCareers?.[0];
 if(selected)return {route:`career-reflection/${selected}`,label:'Continue exploring a saved career'};
 if(Object.values(state.results?.interest?.scores||{}).some(v=>String(v).trim()))return {route:'report',label:'Review your exploration brief'};
 if(state.actions?.length)return {route:'plan',label:'Continue your next-step plan'};
 if(completedCount(state))return {route:'explore',label:'Continue your reflections'};
 return null;
}
export function overviewPage(state){const next=resume(state);return `<div class="page-intro"><div><span class="eyebrow">A PLACE TO BEGIN</span><h1>${state.profile.nickname?`Your next chapter, ${h(state.profile.nickname)}.`:'Your next chapter starts here.'}</h1><p class="intro-copy">Discover the work. Get to know yourself. Try one small next step.</p></div><a class="button secondary" href="#/example">See an example brief ↗</a></div>
 ${next?`<section class="resume-strip"><div><span class="overline">YOUR EXPLORATION CONTINUES</span><h2>Pick up the thread.</h2><p>Your draft is saved in this browser.</p></div><a class="button" href="#/${h(next.route)}">${h(next.label)} →</a></section>`:''}
 <section class="entry-paths" aria-label="Choose a starting point"><article class="entry-path"><span class="entry-number">01</span><span class="overline">SOMETHING IN MIND</span><h2>Follow your curiosity.</h2><p>Search a career, subject, or everyday activity. Explore college, apprenticeships and practical training.</p><a class="button" href="#/catalog">Search majors & careers →</a></article><article class="entry-path"><span class="entry-number">02</span><span class="overline">OPEN TO DISCOVERY</span><h2>Picture the work.</h2><p>Start with making, investigating, helping or creating. See what people actually do each day.</p><a class="button" href="#/discover">Discover possibilities →</a></article><article class="entry-path"><span class="entry-number">03</span><span class="overline">BRING YOUR RESULTS</span><h2>Connect the evidence.</h2><p>Bring an existing assessment. Keep interests, abilities and experiences in their own terms.</p><a class="button" href="#/results">Bring my results →</a></article></section>
 <section class="journey-invitation"><div><span class="overline">YOUR OWN PACE</span><h2>Choose how you want to explore.</h2><p>A quick start or a fuller conversation. You can browse and make a plan without taking a test.</p></div><a class="button secondary" href="#/journey">See the exploration routes →</a></section>
 <section class="journey-bottom"><article><span class="overline">REAL WORK, MANY ROUTES</span><h2>A possibility you can investigate.</h2><p>Compare daily tasks, work settings, preparation and costs. Keep a question alongside each career.</p><a class="text-link" href="#/compare-careers">Open my career comparison →</a></article><article><span class="overline">TRY → NOTICE → REFLECT</span><h2>Small experiences count.</h2><p>A class, a project or a conversation can help you decide what to investigate next.</p><a class="text-link" href="#/plan">Open my next-step plan →</a></article></section>`;}
export function discoverPage(){return `<div class="page-intro"><div><span class="eyebrow">START WITH THE WORK</span><h1>What would you like to try?</h1><p class="intro-copy">Choose an activity or setting to browse. These are ways to explore, not personality types.</p></div><a class="button secondary" href="#/catalog">Browse the whole collection ↗</a></div><section aria-labelledby="activity-browse-title"><h2 id="activity-browse-title">Activities that spark a question</h2><div class="discovery-grid">${options(workActivityOptions).map(x=>`<button class="discovery-choice" data-action="discover-activity" data-id="${h(x.id)}"><span>${h(x.label)}</span><span aria-hidden="true">→</span></button>`).join('')}</div></section><section class="discovery-settings" aria-labelledby="setting-browse-title"><h2 id="setting-browse-title">Places you can picture</h2><div class="discovery-grid">${options(settingOptions).map(x=>`<button class="discovery-choice" data-action="discover-setting" data-id="${h(x.id)}"><span>${h(x.label)}</span><span aria-hidden="true">→</span></button>`).join('')}</div></section><section class="journey-invitation"><div><h2>Still finding your starting point?</h2><p>Explore your interests through an official assessment or your own experiences.</p></div><a class="button secondary" href="#/journey">Choose an exploration route →</a></section>`;}
const actionText=(a,key,label)=>`<div class="field"><label for="action-${h(a.id)}-${key}">${label}</label><textarea id="action-${h(a.id)}-${key}" data-plan-action="${h(a.id)}" data-plan-field="${key}" maxlength="2000">${h(a[key]||'')}</textarea></div>`;
export function plannerPage(state){const done=state.actions.filter(a=>a.done).length;return `<div class="page-intro"><div><span class="eyebrow">TRY → NOTICE → REFLECT</span><h1>One small step. A better question.</h1><p class="intro-copy">Choose an experience, plan the support you need, then notice what it teaches you.</p></div><button class="button secondary" data-action="new-action">Add my own step +</button></div>${state.actions.length?`<p class="plan-stat">${done} of ${state.actions.length} experiments marked complete</p><div class="experiment-list">${state.actions.map(a=>`<article class="experiment-card ${a.done?'done':''}" id="experiment-${h(a.id)}"><header><label class="experiment-done"><input type="checkbox" data-action-check="${h(a.id)}" ${a.done?'checked':''}><span class="sr-only">Complete step: ${h(a.title)}</span></label><div><h2>${h(a.title)}</h2>${a.careerId&&occupationById(a.careerId)?`<a href="#/career/${h(a.careerId)}">${h(occupationById(a.careerId).title)} ↗</a>`:''}<p>${h(a.detail)}</p></div><button class="icon-button" data-action="remove-action" data-id="${h(a.id)}" aria-label="Remove ${h(a.title)}">×</button></header><div class="experiment-inputs"><div class="field"><label for="action-${h(a.id)}-dueDate">When would I like to try it? · optional</label><input type="date" id="action-${h(a.id)}-dueDate" data-plan-action="${h(a.id)}" data-plan-field="dueDate" value="${h(a.dueDate||'')}"></div>${actionText(a,'support','What support would help?')}${actionText(a,'notice','What do I want to notice?')}</div><details class="experiment-review" ${a.done?'open':''}><summary>Reflect on what happened</summary><div class="experiment-inputs">${actionText(a,'enjoyed','What did I enjoy?')}${actionText(a,'difficult','What felt difficult?')}${actionText(a,'surprising','What surprised me?')}${actionText(a,'learned','What did I learn or want to ask next?')}<div class="field"><label for="action-${h(a.id)}-continueDecision">What would I like to do now?</label><select id="action-${h(a.id)}-continueDecision" data-plan-action="${h(a.id)}" data-plan-field="continueDecision">${[['','Not decided'],['continue','Keep exploring'],['questions','Ask more questions'],['later','Set aside for now']].map(([v,l])=>`<option value="${v}" ${a.continueDecision===v?'selected':''}>${l}</option>`).join('')}</select></div></div></details></article>`).join('')}</div>`:`<section class="empty-state"><h2>Give one possibility a little attention.</h2><p>Save a career experiment, or add a class, conversation or project of your own.</p><div class="button-group"><a class="button" href="#/catalog">Explore careers →</a><button class="button secondary" data-action="new-action">Add my own step +</button></div></section>`}<section class="journey-invitation"><div><h2>Your experience can change the question.</h2><p>Reflections stay separate from standardized scores. You choose what to share with a counselor.</p></div><a class="button secondary" href="#/report">Review my exploration brief →</a></section>`;}
export function actionEditorFields(a={}){return `<div class="field"><label class="label" for="action-title">My next step</label><input type="text" id="action-title" name="title" required maxlength="200" value="${h(a.title||'')}" placeholder="For example: ask someone about a typical workday"></div><div class="field"><label class="label" for="action-detail">What will I do?</label><textarea id="action-detail" name="detail" maxlength="2000">${h(a.detail||'')}</textarea></div><div class="form-row"><div class="field"><label class="label" for="action-dueDate">When? · optional</label><input type="date" id="action-dueDate" name="dueDate" value="${h(a.dueDate||'')}"></div><div class="field"><label class="label" for="action-support">What support do I need?</label><input id="action-support" name="support" maxlength="2000" value="${h(a.support||'')}"></div></div><div class="field"><label class="label" for="action-notice">What do I want to notice?</label><textarea id="action-notice" name="notice" maxlength="2000">${h(a.notice||'')}</textarea></div>`;}
